/* Translational shifting paths */
@keyframes sweepBG {
  0% { translate: -200px 0; }
  50% { translate: 200px 0; }
  100% { translate: -200px 0; }
}

@keyframes sweepFG {
  0% { translate: 140px -30px; }
  25% { translate: -60px 20px; }
  50% { translate: -130px -10px; }
  75% { translate: 50px 25px; }
  100% { translate: 140px -30px; }
}

/* Scaling updates */
@keyframes scaleBG {
  0% { scale: var(--shape-scale-min); }
  50% { scale: var(--shape-scale-max); }
  100% { scale: var(--shape-scale-min); }
}

@keyframes scaleFG {
