  50% { scale: var(--shape-scale-min); }
  100% { scale: var(--shape-scale-max); }
}

/* Rotational updates */
@keyframes rotateFG {
  0% { transform: rotate(var(--fg-rotate-min)); }
  50% { transform: rotate(var(--fg-rotate-max)); }
  100% { transform: rotate(var(--fg-rotate-min)); }
}
