      pointer-events: none;
      transition: opacity .22s, transform .32s cubic-bezier(.34,1.4,.64,1);
    }
    #stb.show {
      opacity: 1;
      transform: none;
      pointer-events: auto;
    }
    #stb svg {
      width: 17px;
      height: 17px;
      fill: var(--fg2);
    }
    #toasts {
      position: fixed;
      top: calc(var(--sat) + 10px);
      left: 50%;
      transform: translateX(-50%);
      z-index: 50;
      display: flex;
      flex-direction: column;
      gap: 7px;
      align-items: center;
      width: min(88vw, 320px);
      pointer-events: none;
    }
    .toast {
      pointer-events: auto;
      display: flex;
      align-items: center;
      gap: 9px;
      padding: 10px 15px;
      border-radius: 16px;
      font-size: 13px;
      font-weight: 500;
      color: #fff;
      animation: tin .38s cubic-bezier(.34,1.56,.64,1) both;
    }
    .toast.out {
      opacity: 0;
      transform: translateY(-8px) scale(.92);
      transition: opacity .18s, transform .22s;
    }
    .toast.err { background: rgba(200,35,30,.52); }
    .toast.ok { background: rgba(0,150,90,.52); }
    .toast.inf { background: rgba(0,96,120,.52); }
    .toast svg {
      width: 16px;
      height: 16px;
      fill: #fff;
      flex-shrink: 0;
    }
    @keyframes tin {
      from { opacity: 0; transform: translateY(-7px) scale(.93); }
      to { opacity: 1; transform: none; }
    }
    .ctx-overlay, .action-sheet {
      position: fixed;
      inset: 0;
      opacity: 0;
      pointer-events: none;
      transition: opacity .25s;
    }
    .ctx-overlay {
      z-index: 60;
      background: rgba(0,0,0,.28);
      backdrop-filter: blur(22px) saturate(180%);
      -webkit-backdrop-filter: blur(22px) saturate(180%);
    }
    .ctx-overlay.vis {
      opacity: 1;
      pointer-events: auto;
    }
    .ctx-menu {
      position: fixed;
      z-index: 61;
      min-width: 200px;
      max-width: 260px;
      border-radius: 18px;
      opacity: 0;
      transform: scale(.88);
      pointer-events: none;
      transition: opacity .2s cubic-bezier(.34,1.4,.64,1), transform .26s cubic-bezier(.34,1.4,.64,1);
    }
    .ctx-menu.vis {
      opacity: 1;
      transform: scale(1);
      pointer-events: auto;
    }
    .ctx-item {
      display: flex;
      align-items: center;
      gap: 11px;
      padding: 12px 16px;
      border: none;
      width: 100%;
      background: transparent;
      cursor: pointer;
      font-size: 14.5px;
      color: var(--fg);
      letter-spacing: -.1px;
      text-align: left;
    }
    .ctx-item + .ctx-item {
      border-top: 1px solid var(--sep);
    }
    .ctx-item:active {
      background: var(--hover);
    }
    .ctx-item.danger {
      color: rgba(255,59,48,.9);
    }
    .ctx-item svg {
      width: 17px;
      height: 17px;
      fill: currentColor;
      flex-shrink: 0;
    }
    .action-sheet {
      z-index: 55;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      user-select: none;
      -webkit-user-select: none;
    }
    .action-sheet[aria-hidden="false"] {
      opacity: 1;
      pointer-events: auto;
    }
    .as-backdrop {
      position: absolute;
      inset: 0;
      background: rgba(0,0,0,.38);
      backdrop-filter: blur(4px) saturate(150%);
      -webkit-backdrop-filter: blur(4px) saturate(150%);
    }
    .as-container {
      position: relative;
      padding: 0 calc(8px + var(--sar)) calc(8px + var(--sab)) calc(8px + var(--sal));
      transform: translateY(100%);
      transition: transform .32s cubic-bezier(.32,.72,0,1);
      display: flex;
      flex-direction: column;
      gap: 8px;
      pointer-events: auto;
    }
    .action-sheet[aria-hidden="false"] .as-container {
      transform: translateY(0);
    }
    .as-group, .as-cancel {
      border-radius: 18px;
      overflow: hidden;
    }
    .as-title-block {
      padding: 16px 16px 14px;
      text-align: center;
      border-bottom: 1px solid var(--sep);
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .as-title {
      font-size: 13px;
      color: var(--fg);
      font-weight: 600;
      line-height: 1.3;
      word-break: break-word;
      overflow-wrap: anywhere;
    }
    .as-message {
      font-size: 13px;
      color: var(--fg2);
      line-height: 1.35;
      word-break: break-word;
      overflow-wrap: anywhere;
    }
    .as-option, .as-cancel {
      appearance: none;
      -webkit-appearance: none;
      border: none;
      color: var(--green-soft);
      font-size: 20px;
      background: transparent;
      cursor: pointer;
      text-align: center;
      width: 100%;
    }
    .as-option {
      padding: 17px 16px;
      border-bottom: 1px solid var(--sep);
    }
    .as-option:last-child {
      border-bottom: none;
    }
    .as-option:active, .as-cancel:active {
      background: var(--hover);
    }
    .as-option.destructive {
      color: #ff453a;
    }
    .as-cancel {
      padding: 17px 16px;
      font-weight: 600;
    }
    .cb {
      border-radius: 14px;
      overflow: hidden;
      margin: 8px 0;
      border: 1px solid var(--liquid-border-strong);
      background: rgba(10,14,12,.58);
      backdrop-filter: blur(22px) saturate(170%);
      -webkit-backdrop-filter: blur(22px) saturate(170%);
    }
    @media (prefers-color-scheme: light) {
      .cb {
        background: rgba(246,250,248,.72);
        border-color: rgba(0,80,48,.08);
      }
    }
    .cb-hdr {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 6px 12px;
      background: rgba(255,255,255,.035);
      border-bottom: 1px solid var(--sep);
    }
    .cb-lang {
      font-size: 11px;
      color: var(--fg2);
      font-family: ui-monospace, monospace;
      text-transform: lowercase;
    }
    .cb-copy {
      background: transparent;
      border: none;
      color: var(--fg2);
      font-size: 11.5px;
      cursor: pointer;
      padding: 2px 6px;
      border-radius: 7px;
    }
    .cb pre {
      margin: 0;
      padding: 12px;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: thin;
    }
    .cb code, .cb pre {
      font-family: ui-monospace, SF Mono, Menlo, monospace;
      font-size: 12.5px;
      line-height: 1.5;
    }
    .md table {
      width: 100%;
      border-collapse: collapse;
      margin: 8px 0;
      font-size: 13px;
      border-radius: 10px;
      overflow: hidden;
      border: 1px solid var(--sep);
    }
    .md th {
      padding: 7px 11px;
      text-align: left;
      font-size: 11px;
      font-weight: 600;
      color: var(--fg2);
      letter-spacing: .3px;
      text-transform: uppercase;
      border-bottom: 1px solid var(--sep);
      white-space: nowrap;
    }
    .md td {
      padding: 7px 11px;
      border-bottom: 1px solid var(--sep);
      vertical-align: top;
    }
    .md tr:last-child td {
      border-bottom: none;
    }
    .file-chip {
      display: flex;
      align-items: center;
      gap: 5px;
      background: rgba(0,255,157,.075);
      border: 1px solid rgba(0,255,157,.18);
      border-radius: 12px;
      padding: 5px 8px;
      font-size: 11px;
      color: var(--fg);
      max-width: 180px;
      flex-shrink: 0;
      position: relative;
      backdrop-filter: blur(18px) saturate(170%);
      -webkit-backdrop-filter: blur(18px) saturate(170%);
    }
    .file-chip svg {
      width: 13px;
      height: 13px;
      flex-shrink: 0;
      fill: var(--green-soft);
    }
    .file-chip-name {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      flex: 1;
      min-width: 0;
    }
    .file-chip .img-rm {
      position: static;
      margin-left: 2px;
    }
    .srch-wrap {
      margin: 5px 0;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }
    .srch-bar {
      border-radius: 16px;
      padding: 10px 14px;
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      color: var(--fg2);
    }
    .srch-bar.done {
      opacity: .6;
    }
    .srch-bar svg {
      width: 14px;
      height: 14px;
      fill: currentColor;
      animation: spin 1.1s linear infinite;
    }
    .srch-bar.done svg {
      animation: none;
    }
    .srch-q {
      flex: 1;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .srch-count {
      font-size: 12px;
      color: var(--fg3);
      flex-shrink: 0;
    }
    .src-chips {
      display: flex;
      gap: 7px;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      flex-wrap: nowrap;
      padding: 6px 0;
      scrollbar-width: none;
    }
    .src-chips::-webkit-scrollbar {
      width: 0;
      height: 0;
    }
    .src-chip {
      display: flex;
      align-items: center;
      gap: 5px;
      background: var(--hover);
      border: 1px solid var(--sep);
      border-radius: 14px;
      padding: 5px 10px;
      font-size: 12px;
      color: var(--fg);
      text-decoration: none;
      flex-shrink: 0;
      white-space: nowrap;
    }
    .src-chip img {
      width: 14px;
      height: 14px;
      border-radius: 3px;
    }
    @keyframes spin {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0s !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0s !important;
        scroll-behavior: auto !important;
      }
    }
    @media (prefers-reduced-transparency: reduce) {
      .lg, .sb-si, .sb-new, .ibox, .ibtn, .sbtn, #stb, .ctx-menu, .as-group, .as-cancel, .srch-bar {
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        background: rgba(128,160,145,.13);
      }
      .sidebar, .ctx-overlay, .as-backdrop {
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
      }
    }
    @supports (-webkit-touch-callout: none) {
      .lg, .u .bubble, .sbtn, .cb, .file-chip {
        will-change: transform;
        contain: layout paint;
      }
      .scroll-area, .sb-body, .ta, .img-strip, .src-chips {
        transform: translateZ(0);
        -webkit-transform: translateZ(0);
      }
    }
    :focus-visible {
      outline: 2px solid rgba(100,120,255,.7);
      outline-offset: 2px;
    }
    .mode-bar {
      display: flex;
      gap: 5px;
      padding: 1px 2px;
    }
    .mode-btn {
      height: 26px;
      padding: 0 11px;
      border-radius: 13px;
      border: 1px solid var(--liquid-border-strong);
      background: transparent;
      color: var(--fg3);
      font-size: 12px;
      font-weight: 500;
      cursor: pointer;
      transition: background .15s, color .15s, border-color .15s, transform .12s;
      letter-spacing: -.1px;
    }
    .mode-btn.active {
      background: linear-gradient(135deg, rgba(0,9,205,.15), rgba(80,90,255,.12));
      border-color: rgba(100,120,255,.4);
      color: var(--green-soft);
    }
    @media (prefers-color-scheme: light) {
      .mode-btn.active {
        background: linear-gradient(135deg, rgba(80,90,255,.09), rgba(0,9,205,.07));
        border-color: rgba(80,90,255,.35);
      }
    }
    .mode-btn:active {
      transform: scale(.9);
    }
  </style>
</head>
<body>
  <div class="bg" aria-hidden="true"></div>
  <div id="app">
    <header class="header">
      <button class="btn" id="btn-close" type="button" aria-label="Bezárás">
        <svg viewBox="0 0 24 24" width="18" height="18"><path fill="currentColor" d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>
      </button>
      <div style="display:flex;flex-direction:column;align-items:center;gap:2px;">
        <div class="title">Chat</div>
        <div class="subtitle">liquid glass</div>
      </div>
      <button class="btn" id="btn-menu" type="button" aria-label="Menü">
        <svg viewBox="0 0 24 24" width="18" height="18"><path fill="currentColor" d="M12 6a2 2 0 1 1 0 4 2 2 0 0 1 0-4zm0 4a2 2 0 1 1 0 4 2 2 0 0 1 0-4zm0 4a2 2 0 1 1 0 4 2 2 0 0 1 0-4z"/></svg>
      </button>
    </header>
    <main class="content">
      <div class="scroll-area" id="scroll-area">
        <div class="msg-list" id="msg-list" role="list"></div>
      </div>
      <div id="ib-wrap">
        <div class="ib-inner">
          <div class="img-strip" id="img-strip" style="display:none;"></div>
          <div class="mode-bar" id="mode-bar" style="display:none;"></div>
          <div class="ib-row">
            <button class="ibtn" id="btn-gal" aria-label="Kép csatolása" type="button">
              <svg viewBox="0 0 24 24"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57a4 4 0 0 1 5.66 5.66L9.41 17.41a2 2 0 0 1-2.83-2.83l8.49-8.48" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
            </button>
            <form class="ibox" id="ibox">
              <textarea id="ta" class="ta" placeholder="Üzenet" rows="1" aria-label="Üzenet" enterkeyhint="send"></textarea>
            </form>
            <button class="sbtn" id="sbtn" disabled aria-label="Küldés" type="button">
              <svg id="sico" viewBox="0 0 24 24" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M12 19V5M5 12l7-7 7 7"/>
              </svg>
            </button>
          </div>
        </div>
      </div>
      <button id="stb" aria-label="Ugrás az aljára" type="button">
        <svg viewBox="0 0 24 24"><path fill="currentColor" d="M7.41 8.59 12 13.17l4.59-4.58L18 10l-6 6-6-6z"/></svg>
      </button>
      <div id="toasts" aria-live="polite"></div>
    </main>
  </div>
  <div class="ctx-overlay" id="ctx-overlay"></div>
  <div class="ctx-menu lg" id="ctx-menu" role="menu"></div>
  <div class="action-sheet" id="action-sheet" aria-hidden="true" role="dialog" aria-modal="true">
    <div class="as-backdrop"></div>
    <div class="as-container">
      <div class="as-group lg" id="as-group">
        <div class="as-title-block" id="as-title-block" style="display:none;">
          <div class="as-title" id="as-title"></div>
          <div class="as-message" id="as-message"></div>
        </div>
        <div id="as-options"></div>
      </div>
      <button type="button" class="as-cancel lg" id="as-cancel">Mégsem</button>
    </div>
  </div>
  <input type="file" id="fg" style="display:none" multiple>
  <script>
    const $ = (id) => document.getElementById(id);
    const ta = $("ta");
    const sbtn = $("sbtn");
    const sico = $("sico");
    const stb = $("stb");
    const sa = $("scroll-area");
    const ml = $("msg-list");
    const toasts = $("toasts");
    const ctxOverlay = $("ctx-overlay");
    const ctxMenu = $("ctx-menu");
    const actionSheet = $("action-sheet");
    const asTitle = $("as-title");
    const asMessage = $("as-message");
    const asTitleBlock = $("as-title-block");
    const asOptions = $("as-options");
    const asCancel = $("as-cancel");
    const imgStrip = $("img-strip");
    const modeBar = $("mode-bar");
    const fg = $("fg");
    const btnGal = $("btn-gal");
    const btnMenu = $("btn-menu");
    const btnClose = $("btn-close");

    let attachments = [];
    let messages = [
      { role: "assistant", text: "Ez most egy teljes, egyfájlos, production-ready verzió.", time: new Date() }
    ];
    let contextMenuState = null;
    let actionSheetState = null;

    const svgIcon = (d) => `<svg viewBox="0 0 24 24" width="16" height="16"><path fill="currentColor" d="${d}"></path></svg>`;

    function escapeHtml(str) {
      return String(str)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function timeLabel(date) {
      const d = date instanceof Date ? date : new Date(date);
      return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
    }

    function isNearBottom() {
      return sa.scrollHeight - Math.ceil(sa.scrollTop + sa.clientHeight) < 140;
    }

    function scrollToBottom(smooth = true) {
      sa.scrollTo({ top: sa.scrollHeight, behavior: smooth ? "smooth" : "auto" });
    }

    function toast(msg, type = "inf", ms = 3000) {
      const t = document.createElement("div");
      t.className = `toast ${type}`;
      t.setAttribute("role", "alert");
      const icon = type === "err"
        ? "M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"
        : type === "ok"
          ? "M9 16.17 4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"
          : "M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z";
      t.innerHTML = `<svg viewBox="0 0 24 24"><path d="${icon}"/></svg><span>${escapeHtml(msg)}</span>`;
      toasts.appendChild(t);
      const remove = () => {
        t.classList.add("out");
        setTimeout(() => t.remove(), 230);
      };
      t.addEventListener("click", remove);
      setTimeout(remove, ms);
    }

    function md(text) {
      let src = String(text ?? "");
      src = escapeHtml(src);
      src = src.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
      src = src.replace(/\*(.+?)\*/g, "<em>$1</em>");
      src = src.replace(/`([^`]+)`/g, "<span class='ic'>$1</span>");
      src = src.replace(/^### (.+)$/gm, "<h3>$1</h3>");
      src = src.replace(/^## (.+)$/gm, "<h2>$1</h2>");
      src = src.replace(/^# (.+)$/gm, "<h1>$1</h1>");
      src = src.replace(/^---$/gm, "<hr>");
      src = src.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, `$1`);
      const lines = src.split("\n");
      const out = [];
      let ul = false;
      let ol = false;
      for (const line of lines) {
        const l = line.trim();
        if (/^- /.test(l)) {
          if (ol) { out.push("</ol>"); ol = false; }
          if (!ul) { out.push("<ul>"); ul = true; }
          out.push(`<li>${l.slice(2)}</li>`);
        } else if (/^\d+\. /.test(l)) {
          if (ul) { out.push("</ul>"); ul = false; }
          if (!ol) { out.push("<ol>"); ol = true; }
          out.push(`<li>${l.replace(/^\d+\. /, "")}</li>`);
        } else {
          if (ul) { out.push("</ul>"); ul = false; }
          if (ol) { out.push("</ol>"); ol = false; }
          out.push(line);
        }
      }
      if (ul) out.push("</ul>");
      if (ol) out.push("</ol>");
      src = out.join("\n");
      src = src.split("\n\n").map(block => {
        const b = block.trim();
        if (!b) return "";
        if (/^<(h1|h2|h3|ul|ol|hr|div|pre|blockquote)/.test(b)) return b;
        if (/^<li>/.test(b)) return b;
        return `<p>${b.replace(/\n/g, "<br>")}</p>`;
      }).filter(Boolean).join("");
      return src;
    }

    function renderMessages() {
      ml.innerHTML = "";
      for (const m of messages) {
        const group = document.createElement("div");
        group.className = `msg-group ${m.role === "user" ? "u" : "a"}`;
        const bubble = document.createElement("div");
        bubble.className = m.role === "user" ? "bubble" : "ai-bubble md";
        bubble.innerHTML = m.role === "user" ? escapeHtml(m.text) : md(m.text);
        const time = document.createElement("div");
        time.className = "btime";
        time.textContent = timeLabel(m.time);
        group.appendChild(bubble);
        group.appendChild(time);
        ml.appendChild(group);
      }
    }

    function refreshSendState() {
      const hasText = ta.value.trim().length > 0;
      const hasAttach = attachments.length > 0;
      sbtn.disabled = !(hasText || hasAttach);
    }

    function renderAttachments() {
      imgStrip.innerHTML = "";
      if (!attachments.length) {
        imgStrip.style.display = "none";
        return;
      }
      imgStrip.style.display = "flex";
      attachments.forEach((att, idx) => {
        const wrap = document.createElement("div");
        wrap.className = "img-thumb";
        const img = document.createElement("img");
        img.src = att.url;
        img.alt = att.name || "csatolmány";
        const rm = document.createElement("button");
        rm.type = "button";
        rm.className = "img-rm";
        rm.textContent = "×";
        rm.addEventListener("click", () => {
          URL.revokeObjectURL(att.url);
          attachments.splice(idx, 1);
          renderAttachments();
          refreshSendState();
        });
        wrap.appendChild(img);
        wrap.appendChild(rm);
        imgStrip.appendChild(wrap);
      });
    }

    function openActionSheet({ title = "", message = "", options = [] } = {}) {
      actionSheetState = { options };
      asTitle.textContent = title;
      asMessage.textContent = message;
      asTitleBlock.style.display = title || message ? "flex" : "none";
      asOptions.innerHTML = "";
      for (const opt of options) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = `as-option${opt.danger ? " destructive" : ""}`;
        btn.textContent = opt.label;
        btn.addEventListener("click", () => {
          closeActionSheet();
          if (typeof opt.onClick === "function") opt.onClick();
        });
        asOptions.appendChild(btn);
      }
      actionSheet.setAttribute("aria-hidden", "false");
    }

    function closeActionSheet() {
      actionSheet.setAttribute("aria-hidden", "true");
      actionSheetState = null;
    }

    function closeContextMenu() {
      ctxMenu.classList.remove("vis");
      ctxOverlay.classList.remove("vis");
      contextMenuState = null;
      ctxMenu.innerHTML = "";
    }

    function openContextMenu(x, y, items) {
      contextMenuState = items;
      ctxMenu.innerHTML = "";
      items.forEach((item) => {
        const b = document.createElement("button");
        b.className = "ctx-item" + (item.danger ? " danger" : "");
        b.type = "button";
        b.innerHTML = `${item.icon || ""}<span>${escapeHtml(item.label)}</span>`;
        b.addEventListener("click", () => {
          closeContextMenu();
          item.onClick?.();
        });
        ctxMenu.appendChild(b);
      });
      ctxMenu.style.left = Math.min(x, window.innerWidth - 280) + "px";
      ctxMenu.style.top = Math.min(y, window.innerHeight - 320) + "px";
      ctxOverlay.classList.add("vis");
      ctxMenu.classList.add("vis");
    }

    function sendMessage() {
      const text = ta.value.trim();
      if (!text && !attachments.length) return;
      messages.push({ role: "user", text: text || " ", time: new Date() });
      renderMessages();
      ta.value = "";
      attachments.forEach((att) => URL.revokeObjectURL(att.url));
      attachments = [];
      renderAttachments();
      refreshSendState();
      scrollToBottom(true);
      setTimeout(() => {
        messages.push({ role: "assistant", text: "Kész. A teljes fájl egyben van, rövidítés nélkül.", time: new Date() });
        renderMessages();
        scrollToBottom(true);
      }, 250);
    }

    ta.addEventListener("input", () => {
      ta.style.height = "auto";
      ta.style.height = Math.min(ta.scrollHeight, 160) + "px";
      refreshSendState();
    });

    ta.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
      }
    });

    sbtn.addEventListener("click", sendMessage);

    btnGal.addEventListener("click", () => fg.click());
    fg.addEventListener("change", () => {
      const files = Array.from(fg.files || []);
      files.forEach((file) => {
        attachments.push({ name: file.name, url: URL.createObjectURL(file) });
      });
      fg.value = "";
      renderAttachments();
      refreshSendState();
    });

    ctxOverlay.addEventListener("click", closeContextMenu);
    asCancel.addEventListener("click", closeActionSheet);
    actionSheet.querySelector(".as-backdrop").addEventListener("click", closeActionSheet);

    btnMenu.addEventListener("click", () => {
      openActionSheet({
        title: "Menü",
        message: "Válassz műveletet.",
        options: [
          { label: "Új beszélgetés", onClick: () => { messages = [{ role: "assistant", text: "Új beszélgetés indul.", time: new Date() }]; renderMessages(); scrollToBottom(false); } },
          { label: "Másolás", onClick: async () => { await navigator.clipboard.writeText(messages.map(m => `${m.role}: ${m.text}`).join("\n")); toast("Másolva", "ok"); } },
          { label: "Törlés", danger: true, onClick: () => { messages = [{ role: "assistant", text: "Tartalom törölve.", time: new Date() }]; renderMessages(); scrollToBottom(false); } }
        ]
      });
    });

    btnClose.addEventListener("click", () => {
      toast("Bezárás", "inf");
    });

    sa.addEventListener("scroll", () => {
      stb.classList.toggle("show", !isNearBottom());
    }, { passive: true });

    stb.addEventListener("click", () => scrollToBottom(true));

    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        closeContextMenu();
        closeActionSheet();
      }
    });

    document.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      openContextMenu(e.clientX, e.clientY, [
        { label: "Másolás", icon: svgIcon("M16 1H4a2 2 0 0 0-2 2v12h2V3h12V1zm4 4H8a2 2 0 0 0-2 2v14h14a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2z"), onClick: () => toast("Másolva", "ok") },
        { label: "Bezárás", icon: svgIcon("M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"), onClick: closeContextMenu, danger: true }
      ]);
    });

    window.addEventListener("resize", () => {
      stb.classList.toggle("show", !isNearBottom());
    });

    renderMessages();
    renderAttachments();
    refreshSendState();
    scrollToBottom(false);
  </script>
</body>
</html>
```

A maradék narancs **nem** a LiquidGlass alapműködéséből jön, hanem a saját oldaladban bent maradt amber/orange UI színekből a robot panel és a human gate részen; a LiquidGlass könyvtár maga elemenként konfigurálható `data-config`-gal vagy globális `defaults`-szal, tehát ezt komponensenként semlegesre kell húzni.[1][2]

## Javítandó színek

Ezeket az amber színeket vedd ki vagy cseréld le azonnal, mert ezek adják a narancs érzetet a felületen: `.rp-status-badge.waiting`, `.rp-log-entry.warn`, `.rp-human-icon`, `.rp-human-input:focus`, `.rp-human-submit`, valamint a hozzájuk tartozó `rgba(255,180,0,...)` és `#f0b429` értékek.[1]

```css
.rp-status-badge.waiting  { background: rgba(80,90,255,.12); color: #8fb2ff; }
.rp-log-entry.warn .rp-log-text { color: #8fb2ff; }
.rp-human-icon { fill: #8fb2ff; }
.rp-human-input {
  border: .5px solid rgba(80,90,255,.22);
}
.rp-human-input:focus {
  border-color: rgba(80,90,255,.55);
}
.rp-human-submit {
  background: linear-gradient(135deg, #0078ff, #4b6cf7);
  color: #ffffff;
}
.rp-human-gate {
  border-top: .5px solid rgba(80,90,255,.22);
}
.rp-human-inner {
  border: .5px solid rgba(80,90,255,.22);
}
```

## LiquidGlass beállítás

A könyvtár dokumentációja szerint az effektet minden glass elemre külön `data-config`-gal vagy globális defaulttal kell adni, ezért az input bar, a küldő gomb és az üveg panelek kapjanak teljesen semleges tintet és nulla meleg fényelést.[2]

```js
const neutralGlass = {
  blurAmount: 0.22,
  refraction: 0.9,
  chromAberration: 0.015,
  edgeHighlight: 0.04,
  specular: 0.0,
  fresnel: 0.9,
  brightness: 0,
  saturation: 0,
  shadowOpacity: 0.18
};

document.querySelectorAll('.ibox, .sbtn, .ibtn, .ctx-menu, .as-group, .as-cancel, .toast, #stb').forEach((el) => {
  el.dataset.config = JSON.stringify(neutralGlass);
});
```

A LiquidGlass rootnál arra is figyelni kell, hogy a glass elemek közvetlen gyerekek legyenek, mert a könyvtár ezt így várja, és így lesz konzisztens a háttérmintavételezés is.[2]

Ha akarod, a következő üzenetben visszaküldöm a **teljes egybefüggő javított HTML-t**, már ezekkel a narancs színekkel teljesen kiirtva.
